<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;$error='';$id=(int)($_GET['id']??0);$client=$id?one('SELECT id,name,email,role,active FROM users WHERE id=?',[$id]):null;if($id&&!$client){http_response_code(404);exit('Cliente não encontrado.');}if(is_post()&&$client){verify_csrf();try{$name=input('name',120);$email=strtolower(input('email',190));$pass=input('password',200);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Nome ou e-mail inválido.');if(one('SELECT id FROM users WHERE email=? AND id<>?',[$email,$id]))throw new InvalidArgumentException('E-mail indisponível.');$active=isset($_POST['active'])?1:0;if(!$active&&$client['role']==='admin')throw new InvalidArgumentException('O administrador não pode ser bloqueado nesta tela.');if($pass!==''&&strlen($pass)<12)throw new InvalidArgumentException('Senha precisa de 12 caracteres.');if($pass!==''&&(int)$u['id']===$id)throw new InvalidArgumentException('Para mudar sua própria senha, use Minha conta na central do cliente.');run('UPDATE users SET name=?,email=?,active=? WHERE id=?',[$name,$email,$active,$id]);if($pass!=='')run('UPDATE users SET password_hash=? WHERE id=?',[password_hash($pass,PASSWORD_DEFAULT),$id]);audit('cliente_atualizado','Cliente #'.$id);flash('Cliente atualizado. Se redefiniu a senha, envie-a por um canal seguro e oriente a troca.');go('admin/clientes.php?id='.$id);}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}require ROOT.'/includes/panel.php';?><h1>Clientes.</h1><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;if($client):?><form method="post" data-confirm="Confirmar alterações neste cliente?"><?php csrf();?><label class="field">Nome<input name="name" value="<?=e($client['name'])?>" required maxlength="120"></label><label class="field">E-mail<input name="email" value="<?=e($client['email'])?>" type="email" required maxlength="190"></label><label class="field">Redefinir senha (opcional, mínimo 12 caracteres)<input type="password" name="password" minlength="12" maxlength="200" autocomplete="new-password"></label><label class="check"><input type="checkbox" name="active" <?=$client['active']?'checked':''?>>Conta ativa</label><button class="primary">Salvar cliente</button></form><?php else:?><form method="get"><label class="field">Pesquisar nome ou e-mail<input name="busca" value="<?=e(substr((string)($_GET['busca']??''),0,100))?>" maxlength="100"></label><button class="outline">Pesquisar</button></form><div class="table-wrap"><table><tr><th>Cliente</th><th>E-mail</th><th>Perfil</th><th>Status</th><th>Ação</th></tr><?php $q='%'.substr((string)($_GET['busca']??''),0,100).'%';foreach(rows('SELECT id,name,email,role,active FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 300',[$q,$q]) as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['email'])?></td><td><?=e($c['role'])?></td><td><?=$c['active']?'Ativo':'Bloqueado'?></td><td><a href="<?=e(url('admin/clientes.php?id='.$c['id']))?>">Editar ↗</a></td></tr><?php endforeach;?></table></div><?php endif;require ROOT.'/includes/endpanel.php';?>
